#include <queue>
#include <cctype>
#include <cstdio>
#include <vector>
#include <utility>
#include <algorithm>

using namespace std;

const int MAXN = 300;
const int MAXM = 65536;
const int MAX = 12;
const int INF = 1000000007;

inline int rev(int id) { return id ^ 1; }

struct Edge {
    int v, c;
};

vector<int> adj[MAXN];
Edge edge[MAXM * 2];
int nodeCnt, edgeCnt, src, snk;
int cntLabel[MAXN], distLabel[MAXN], curIdx[MAXN], path[MAXN], pathLen;

void initNetwork(int n, int s, int t) {
    nodeCnt = n;
    edgeCnt = 0;
    src = s;
    snk = t;
    for (int i = 0; i < n; ++i) adj[i].clear();
}

void addEdge(int a, int b, int c) {
    edge[edgeCnt].v = b;
    edge[edgeCnt].c = c;
    adj[a].push_back(edgeCnt);
    edge[edgeCnt + 1].v = a;
    edge[edgeCnt + 1].c = 0;
    adj[b].push_back(edgeCnt + 1);
    edgeCnt += 2;
}

void labelBFS() {
    queue<int> q;
    fill(cntLabel, cntLabel + nodeCnt, 0);
    fill(distLabel, distLabel + nodeCnt, nodeCnt);
    distLabel[snk] = 0;
    q.push(snk);
    while (!q.empty()) {
        int u = q.front();
        ++cntLabel[distLabel[u]];
        for (size_t i = 0; i < adj[u].size(); ++i) {
            int id = adj[u][i];
            if (distLabel[edge[id].v] == nodeCnt && edge[rev(id)].c > 0) {
                distLabel[edge[id].v] = distLabel[u] + 1;
                q.push(edge[id].v);
            }
        }
        q.pop();
    }
}

void retreatFlow(int u) {
    --cntLabel[distLabel[u]];
    distLabel[u] = nodeCnt;
    for (size_t i = 0; i < adj[u].size(); ++i) {
        Edge &arc = edge[adj[u][i]];
        if (distLabel[u] > distLabel[arc.v] + 1 && arc.c > 0) {
            distLabel[u] = distLabel[arc.v] + 1;
            curIdx[u] = i;
        }
    }
    ++cntLabel[distLabel[u]];
}

int augmentFlow() {
    int add = 0x7fffff;
    int cut = -1;
    for (int i = 0; i < pathLen; ++i) {
        Edge &arc = edge[adj[path[i]][curIdx[path[i]]]];
        if (arc.c < add) {
            add = arc.c;
            cut = i;
        }
    }
    for (int i = 0; i < pathLen; ++i) {
        int id = adj[path[i]][curIdx[path[i]]];
        edge[id].c -= add;
        edge[rev(id)].c += add;
    }
    pathLen = cut;
    return add;
}

int maxFlowSAP() {
    int flow = 0;
    labelBFS();
    fill(curIdx, curIdx + nodeCnt, 0);
    pathLen = 0;
    path[0] = src;
    while (distLabel[src] != nodeCnt) {
        int u = path[pathLen];
        if (u == snk) {
            flow += augmentFlow();
        } else {
            while (curIdx[u] < (int)adj[u].size()) {
                Edge &arc = edge[adj[u][curIdx[u]]];
                if (distLabel[arc.v] == distLabel[u] - 1 && arc.c > 0) break;
                ++curIdx[u];
            }
            if (curIdx[u] == (int)adj[u].size()) {
                if (cntLabel[distLabel[u]] == 1) break;
                retreatFlow(u);
                if (u != src) --pathLen;
            } else {
                path[++pathLen] = edge[adj[u][curIdx[u]]].v;
            }
        }
    }
    if (flow == 35) --flow;
    return flow;
}

char sci[MAX][MAX], rec[MAX][MAX];
int d[MAX][MAX], t[MAX][MAX];
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, -1, 0, 1};

inline int X(int i, int j) { return i * MAX + j; }
inline int Y(int i, int j) { return MAX * MAX + i * MAX + j; }
inline int S() { return MAX * MAX * 2; }
inline int T() { return S() + 1; }
inline int V() { return T() + 1; }

void bfs(int n) {
    queue<pair<int, int> > q;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            d[i][j] = INF;
            if (sci[i][j] == 'Z') {
                q.push(make_pair(i, j));
                d[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int xx = x + dx[k];
            int yy = y + dy[k];
            if (0 <= xx && xx < n && 0 <= yy && yy < n
                    && isdigit(sci[xx][yy]) && d[xx][yy] == INF) {
                d[xx][yy] = d[x][y] + 1;
                q.push(make_pair(xx, yy));
            }
        }
    }
}

void gao(int n, int range, int sx, int sy) {
    queue<pair<int, int> > q;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            t[i][j] = INF;
        }
    }
    q.push(make_pair(sx, sy));
    t[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        if (t[x][y] > range) break;
        if (t[x][y] <= d[x][y] && isdigit(rec[x][y]) && rec[x][y] != '0') {
            addEdge(X(sx, sy), Y(x, y), 11);
        }
        if (t[x][y] >= d[x][y]) continue;
        for (int k = 0; k < 4; ++k) {
            int xx = x + dx[k];
            int yy = y + dy[k];
            if (0 <= xx && xx < n && 0 <= yy && yy < n
                    && isdigit(sci[xx][yy]) && t[xx][yy] == INF) {
                t[xx][yy] = t[x][y] + 1;
                q.push(make_pair(xx, yy));
            }
        }
    }
}

int main() {
    int n, range;
    scanf("%d%d", &n, &range);
    initNetwork(V(), S(), T());
    for (int i = 0; i < n; ++i) {
        scanf("%s", sci[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(sci[i][j]) && sci[i][j] != '0') {
                addEdge(S(), X(i, j), sci[i][j] - '0');
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        scanf("%s", rec[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(rec[i][j]) && rec[i][j] != '0') {
                addEdge(Y(i, j), T(), rec[i][j] - '0');
            }
        }
    }
    bfs(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(sci[i][j]) && sci[i][j] != '0') {
                gao(n, range, i, j);
            }
        }
    }
    printf("%d\n", maxFlowSAP());
    return 0;
}
